import{c as t,Q as n,j as a,g as e}from"./chunks/framework.hhGiamYR.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-10-14T00:00:00.000Z","source":"machiavelli/discourses/book2/06-第六章"},"headers":[],"relativePath":"fragments/2026-10-14.md","filePath":"fragments/2026-10-14.md"}'),r={name:"fragments/2026-10-14.md"};function s(o,l,u,c,p,d){return n(),a("div",null,[...l[0]||(l[0]=[e("p",null,'罗马人宣战，立刻发兵，六天、十天、二十天，一仗见分晓。我读到这句，心里像被针扎了一下。我们佛罗伦萨围比萨，围了十三年，还在算军饷、还在等雇佣兵到齐。不是罗马人比我们聪明，是他们不敢慢——慢，就是给命运留出翻脸的时间。我组民军那年，就是想把"速"字找回来。结果民军一触即溃。速，不是谁想快就能快的，得先有那一口气，而我们早把那口气花在算计上了。',-1),e("hr",null,null,-1),e("p",null,'"不为戍边者花钱"——罗马人把夺来的土地分给殖民者，让那些人为自己的田产守边疆。读到这句，我停了很久。这就是我毕生想干却干不成的那件事：让守城的人，守的是他自己的东西。雇佣兵不会为一个不归他所有的城池去死，你给多少钱，他就卖多少命。民军不一样，民军身后站着他自己的房、他自己的地。可美第奇回来了，我的民军散了。我这一辈子，都在写"怎样不花钱却有人肯拼命"，可现实里，肯拼命的从来都得先有属于自己的东西。',-1),e("hr",null,null,-1),e("p",null,'"执政官任期只有一年，所以很想结束战争，赢得一次凯旋。"野心，原来是给速度上的发条。我把这句话抄下来，又划掉。因为我想起自己——我要是还有公职，是不是也会为了凯旋而催兵速战？会的。可我现在没了公职，没了任期，没了可以被野心点燃的那个位置。我写的每一个字，都成了一场没有终点的围城。围比萨要十三年，我这围城，怕是得围到死。',-1),e("hr",null,null,-1),e("p",null,"罗马因战争而富裕，别的君主却因不智而被战争搞得穷困潦倒。同样是打仗，一边越打越肥，一边越打越穷。区别不在运气，在怎么处置战利品，在派不派殖民者，在敢不敢速决。我望着这句话，忽然明白我这些年真正想写的，不是君主怎么取国，而是怎么让一件本该流血赔钱的事，变成让人有得赚、有得守的事。取国容易，守国难；守国难在，你得让每一个替你守的人，都觉得这国是他自己的。罗马做到了。意大利做不到。我，也做不到。",-1)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
